def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The motifs are k-by-k, separated by one-cell gutters.
    k = 4 if h == 19 else 3
    stride = k + 1
    nr = (h + stride - 1) // stride
    nc = (w + stride - 1) // stride

    tiles = {}
    for i in range(nr):
        for j in range(nc):
            r0, c0 = i * stride, j * stride
            cells = [(r0 + a, c0 + b) for a in range(k) for b in range(k)
                     if r0 + a < h and c0 + b < w]
            tiles[i, j] = cells

    # Clear the colored target area/separator.
    for r in range(h):
        for c in range(w):
            if out[r][c] == 3:
                out[r][c] = 0

    for (i, j), cells in tiles.items():
        if not cells:
            continue
        # A fully-3 tile is a target: copy the motif from the nearest
        # available tile in its row or column when its indexed cell is set.
        was_target = any(grid[r][c] == 3 for r, c in cells)
        if was_target and all(grid[r][c] == 3 for r, c in cells):
            sources = []
            for jj in range(nc):
                if jj != j:
                    sources.append((i, jj))
            for ii in range(nr):
                if ii != i:
                    sources.append((ii, j))
            src = next((tiles[x] for x in sources
                        if any(grid[r][c] == 2 for r, c in tiles[x])), None)
            if src is not None:
                src_vals = {(r - (src[0][0] // stride) * stride,
                             c - (src[0][1] // stride) * stride): grid[r][c]
                            for r, c in src}
                for r, c in cells:
                    a, b = r - i * stride, c - j * stride
                    if src_vals.get((a, b), 0) == 2:
                        out[r][c] = 2

        a, b = i, j
        r, c = i * stride + a, j * stride + b
        if r < h and c < w and out[r][c] == 2:
            out[r][c] = 8

    return out
