def transform(grid):
    h, w = len(grid), len(grid[0])
    size = 4 if h == 19 else 3
    stride = size + 1
    nr = (h + stride - 1) // stride
    nc = (w + stride - 1) // stride
    out = [row[:] for row in grid]

    # Locate the horizontal or vertical band of 3s.
    target_rows = [r for r in range(h) if all(v == 3 for v in grid[r])]
    target_cols = [c for c in range(w) if all(grid[r][c] == 3 for r in range(h))]
    row_band = bool(target_rows)
    target_index = (target_rows[0] // stride if row_band
                    else target_cols[0] // stride)

    # Clear the 3 band.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                out[r][c] = 0

    def tile_has_2(tr, tc):
        r0, c0 = tr * stride, tc * stride
        return any(r0 + a < h and c0 + b < w and grid[r0 + a][c0 + b] == 2
                   for a in range(size) for b in range(size))

    def tile_value(tr, tc, a, b):
        r, c = tr * stride + a, tc * stride + b
        return grid[r][c] if r < h and c < w else 0

    # Restore only those tiles whose source has a 2 at the board-indexed
    # cell; copy the source tile from the opposite side of the 3 band.
    if row_band:
        for tc in range(nc):
            sources = [tr for tr in range(nr)
                       if tr != target_index and tile_has_2(tr, tc)
                       and tile_value(tr, tc, target_index, tc) == 2]
            if sources:
                sr = min(sources, key=lambda tr: abs(tr - target_index))
                for a in range(size):
                    for b in range(size):
                        r, c = target_index * stride + a, tc * stride + b
                        if r < h and c < w:
                            out[r][c] = tile_value(sr, tc, a, b)
    else:
        for tr in range(nr):
            sources = [tc for tc in range(nc)
                       if tc != target_index and tile_has_2(tr, tc)
                       and tile_value(tr, tc, tr, target_index) == 2]
            if sources:
                sc = min(sources, key=lambda tc: abs(tc - target_index))
                for a in range(size):
                    for b in range(size):
                        r, c = tr * stride + a, target_index * stride + b
                        if r < h and c < w:
                            out[r][c] = tile_value(tr, sc, a, b)

    # Mark the cell indexed by each tile's position.
    for tr in range(nr):
        for tc in range(nc):
            r, c = tr * stride + tr, tc * stride + tc
            if r < h and c < w and out[r][c] == 2:
                out[r][c] = 8

    return out
